```ts
export interface Receipt { id: number; tenant: string; key: string; cents: number }

export class Ledger {
  readonly entries: Receipt[] = [];
  private readonly receiptsByTenant = new Map<string, Map<string, Receipt>>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // Read-check-write below runs without awaiting, so concurrent apply() calls
    // for the same tenant/key cannot interleave: exactly one debit happens.
    let byKey = this.receiptsByTenant.get(tenant);
    if (byKey === undefined) {
      byKey = new Map<string, Receipt>();
      this.receiptsByTenant.set(tenant, byKey);
    }
    const existing = byKey.get(key);
    if (existing !== undefined) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    byKey.set(key, receipt);
    return receipt;
  }
}
```

